import{_ as r,l as n,o as a,c as s,v as t,p as l,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"单调栈与单调队列","description":"","frontmatter":{"title":"单调栈与单调队列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/monotonic-stack-queue.md","filePath":"cs/monotonic-stack-queue.md","lastUpdated":1789023840000}'),h={name:"cs/monotonic-stack-queue.md"};function u(m,e,_,E,A,f){const i=n("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="单调栈与单调队列" tabindex="-1">单调栈与单调队列 <a class="header-anchor" href="#单调栈与单调队列" aria-label="Permalink to &quot;单调栈与单调队列&quot;">​</a></h1><div class="epigraph"><p>从左扫到右，栈里只留「还可能成为下一次最值或最近更矮柱」的下标；过期的从队头丢掉，新来的从队尾挤掉更差的。</p><footer>—— 据 Knuth, The Art of Computer Programming；Sedgewick and Wayne；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/persistent-segment-tree">上一课</a>用树回答任意历史区间。许多问题其实只扫一遍：每个位置找左边第一个更小，或滑动窗口最小值。用线段树是 \\(O(n\\log n)\\) 杀鸡。<a href="/cs/deque">双端队列</a>已经提供两端 \\(O(1)\\)。本课不重开路径复制。缺口是单调栈/单调队列：维护候选下标的单调性，摊还 \\(O(n)\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直方图最大矩形、接雨水、每个元素的最近更小，都要「左边最近的严格更小下标」。暴力向左扫最坏 \\(\\Theta(n^2)\\)。缺口是：下标从左入栈，保持栈中 \\(A\\) 单调（例如递增）；新来的 \\(i\\) 不断弹到栈顶 \\(\\lt A[i]\\)，此时栈顶就是 \\(i\\) 的左边界。每个下标至多进栈出栈一次，合计 \\(\\Theta(n)\\)。</p><p>滑动窗口 \\([i-k+1,i]\\) 的最值：队头过期（下标 \\(\\le i-k\\)）弹出；队尾若比新元素更差（更不可能当窗口最值）则弹，再把 \\(i\\) 入队。队头即当前最值下标。</p><p><span class="marginnote">「单调」指结构内存的键或值单调，不是指输入已排序。窗口队列要 deque，单端栈不够弹头。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>栈：数组当下标栈即可，不必链表。队列：与<a href="/cs/deque">deque</a> 合同一致，头出过期、尾出劣解。严格与非严格比较决定「相等时谁留下」，合同要写清，否则边界差一。</p>',9)),(a(),l(p,null,{default:o(()=>[c(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20I%5B%22%E6%96%B0%E4%B8%8B%E6%A0%87%20i%22%5D%20--%3E%20POP%5B%22%E5%BC%B9%E5%88%B0%E5%8D%95%E8%B0%83%E6%81%A2%E5%A4%8D%22%5D%0A%20%20POP%20--%3E%20PUSH%5B%22i%20%E5%85%A5%E6%A0%88%E6%88%96%E5%85%A5%E9%98%9F%22%5D%0A%20%20HEAD%5B%22%E9%98%9F%E5%A4%B4%E8%BF%87%E7%AA%97%22%5D%20--%3E%20DROP%5B%22%E4%BB%8E%E5%A4%B4%E4%B8%A2%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与线段树：这里不支持任意 \\([l,r]\\) 事后查询，只支持扫描过程中的近邻或固定窗口。需要任意 RMQ 仍用稀疏表或树。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>摊还：每次弹是此前某次 push 的对应。势能可用栈大小。正确性：被弹掉的要么过期，要么中间有更好的候选挡着，后面窗口/近邻不会再需要它。</p><p>这是序列扫描技巧，不是平衡树。局部性好：栈/队列是连续下标数组。不要在教学里用单调栈去「替代」可更新 RMQ。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把笛卡尔树、或单调栈优化 DP 的全部转移式写完。只钉结构合同。二维、任意子矩阵最值不是扫一遍能结束的。下一课分块：当查询形状不规则、又要在线改一部分时，用 \\(\\sqrt{n}\\) 折中。</p><p>后课默认：近邻与滑动窗口最值先想单调栈/队列。更杂的区间统计用分块或树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单调栈：\\(O(n)\\) 最近更小/更大。</li><li>单调队列：滑动窗口最值，头过期尾淘汰。</li><li>任意区间与更新仍要树或分块。</li><li>出处：Knuth；Sedgewick and Wayne；Cormen et al.。</li></ul>',9))])}const P=r(h,[["render",u]]);export{q as __pageData,P as default};
